"use strict";(self.webpackChunkhalt_website=self.webpackChunkhalt_website||[]).push([[44907],{24998:e=>{e.exports=JSON.parse('{"tag":{"label":"Heart Disease","permalink":"/docs/tags/heart-disease","allTagsPath":"/docs/tags","count":6,"items":[{"id":"guinea-pigs/illnesses-and-conditions/bumblefoot-in-guinea-pigs","title":"Bumblefoot in Guinea Pigs","description":"Learn about bumblefoot (pododermatitis) in guinea pigs \u2014 causes including heart disease, warning signs, treatment, and how to prevent this painful foot condition.","permalink":"/docs/guinea-pigs/illnesses-and-conditions/bumblefoot-in-guinea-pigs"},{"id":"Ferrets/illnesses-and-conditions/common-health-issues","title":"Common Health Issues in Ferrets","description":"An overview of the most common health issues affecting pet ferrets, with a strong emphasis on cancers like adrenal disease, insulinoma, and lymphoma, as well as heart disease and GI obstructions.","permalink":"/docs/Ferrets/illnesses-and-conditions/common-health-issues"},{"id":"guinea-pigs/illnesses-and-conditions/fetal-arrhythmia","title":"Fetal Arrhythmia in Guinea Pigs: What It Is and What It Means","description":"Pregnancy in guinea pigs can be a delicate time, requiring close monitoring and appropriate veterinary care. One rare but important condition that can arise is fetal arrhythmia, an irregular heartbeat detected in a developing fetus. While unsettling to hear about, understanding this condition can help owners and rescues make informed decisions.","permalink":"/docs/guinea-pigs/illnesses-and-conditions/fetal-arrhythmia"},{"id":"Chinchillas/illnesses-and-conditions/heartdisease","title":"Heart Disease and Heart Failure in Chinchillas","description":"Heart disease is far more common in chinchillas than previously recognized. A landmark 2012 study published in the Journal of the American Veterinary Medical Association found that 23% of chinchillas examined had heart murmurs, and of those evaluated with echocardiography, the majority had confirmed cardiac abnormalities. This is not a rare condition \u2014 it is a significant and underdiagnosed health concern that every chinchilla owner should understand.","permalink":"/docs/Chinchillas/illnesses-and-conditions/heartdisease"},{"id":"Ferrets/illnesses-and-conditions/heart-disease","title":"Heart Disease in Ferrets","description":"A guide to heart disease in ferrets, a common condition in middle-aged and older animals, covering the signs of congestive heart failure, diagnosis, and medical management.","permalink":"/docs/Ferrets/illnesses-and-conditions/heart-disease"},{"id":"Hedgehogs/illnesses-and-conditions/heart-disease","title":"Heart Disease in Hedgehogs","description":"A guide to heart disease in hedgehogs, particularly Dilated Cardiomyopathy (DCM), a common condition in the species, covering its signs, diagnosis, and management.","permalink":"/docs/Hedgehogs/illnesses-and-conditions/heart-disease"}],"unlisted":false}}')}}]);